/* Open fonts (FORK-050, FORK-051): registry, placement and field images. See open_fonts.h. */
#include "open_fonts.h"

#include <algorithm>
#include <array>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <string>
#include <unordered_map>

#include "png_decode.h"
#include "third_party/picojson/picojson.h"

extern "C" {
/* Generated by port/fast3d/open_fonts_embed.cmake from port/fast3d/open_assets. */
extern const unsigned char open_title_atlas_png[];
extern const size_t open_title_atlas_png_size;
extern const unsigned char open_title_metrics_json[];
extern const size_t open_title_metrics_json_size;
extern const unsigned char open_body_atlas_png[];
extern const size_t open_body_atlas_png_size;
extern const unsigned char open_body_metrics_json[];
extern const size_t open_body_metrics_json_size;
}

namespace open_fonts {
namespace {

constexpr int kGlyphs = 94;  /* printable ASCII, 0x21..0x7E */

struct Cell {
    float advance = 0;
    float ink_left = 0, ink_right = 0;               /* font units */
    float plane_left = 0, plane_bottom = 0, plane_right = 0, plane_top = 0;
    int atlas_x = 0, atlas_y = 0, atlas_w = 0, atlas_h = 0;
    bool present = false;
};

struct Atlas {
    bool loaded = false, ok = false;
    std::vector<uint8_t> rgba;
    int width = 0, height = 0;
    float units_per_em = 1000, cap_height = 700, px_per_em = 48;
    std::array<Cell, kGlyphs> cells;
};

struct RomGlyph {
    const uint8_t *pixels = nullptr;
    int width = 0, height = 0, baseline = 0;
};

}  // namespace

struct Glyph {
    int font = 0, index = 0;
    RomGlyph rom;
};

namespace {

/* ROM font 0 (Bank Gothic) draws with the title font, font 1 (Zurich Bold)
 * with the body font. */
constexpr int kFonts = 2;
struct Source {
    const char *name;
    const unsigned char *png, *metrics;
    const size_t *png_size, *metrics_size;
};
const Source kSources[kFonts] = {
    {"title", open_title_atlas_png, open_title_metrics_json, &open_title_atlas_png_size, &open_title_metrics_json_size},
    {"body", open_body_atlas_png, open_body_metrics_json, &open_body_atlas_png_size, &open_body_metrics_json_size},
};

std::array<std::array<RomGlyph, kGlyphs>, kFonts> g_fonts;
std::unordered_map<const uint8_t *, Glyph> g_registry;
std::array<Atlas, kFonts> g_atlases;

bool parse_metrics(const char *text, size_t size, Atlas &atlas) {
    picojson::value root;
    const std::string error = picojson::parse(root, std::string(text, size));
    if (!error.empty() || !root.is<picojson::object>()) return false;
    const picojson::object &doc = root.get<picojson::object>();
    auto number = [](const picojson::object &o, const char *key) {
        auto it = o.find(key);
        return (it != o.end() && it->second.is<double>()) ? float(it->second.get<double>()) : 0.0f;
    };
    atlas.units_per_em = number(doc, "unitsPerEm");
    atlas.cap_height = number(doc, "capHeight");
    auto at = doc.find("atlas");
    auto glyphs = doc.find("glyphs");
    if (at == doc.end() || glyphs == doc.end() || !glyphs->second.is<picojson::object>()) return false;
    atlas.px_per_em = number(at->second.get<picojson::object>(), "pxPerEm");
    for (const auto &[ch, value] : glyphs->second.get<picojson::object>()) {
        if (ch.size() != 1 || ch[0] < 0x21 || ch[0] > 0x7e || !value.is<picojson::object>()) continue;
        const picojson::object &g = value.get<picojson::object>();
        auto list = [&](const char *key) {
            std::array<float, 4> v{};
            auto it = g.find(key);
            if (it == g.end() || !it->second.is<picojson::array>()) return v;
            const auto &a = it->second.get<picojson::array>();
            for (size_t i = 0; i < 4 && i < a.size(); i++) v[i] = a[i].is<double>() ? float(a[i].get<double>()) : 0;
            return v;
        };
        Cell &cell = atlas.cells[ch[0] - 0x21];
        const auto bounds = list("bounds"), plane = list("plane"), rect = list("atlas");
        cell.advance = number(g, "advance");
        cell.ink_left = bounds[0];
        cell.ink_right = bounds[2];
        cell.plane_left = plane[0];
        cell.plane_bottom = plane[1];
        cell.plane_right = plane[2];
        cell.plane_top = plane[3];
        cell.atlas_x = int(rect[0]);
        cell.atlas_y = int(rect[1]);
        cell.atlas_w = int(rect[2]);
        cell.atlas_h = int(rect[3]);
        cell.present = cell.atlas_w > 0 && cell.atlas_h > 0;
    }
    return atlas.units_per_em > 0 && atlas.cap_height > 0 && atlas.px_per_em > 0;
}

const Atlas &font_atlas(int font) {
    Atlas &atlas = g_atlases[font];
    if (!atlas.loaded) {
        const Source &src = kSources[font];
        atlas.loaded = true;
        atlas.ok = png_decode::rgba(src.png, *src.png_size, atlas.rgba, atlas.width, atlas.height)
                   && parse_metrics(reinterpret_cast<const char *>(src.metrics), *src.metrics_size, atlas);
        if (!atlas.ok) fprintf(stderr, "ge: open fonts: the %s font atlas could not be loaded; ROM glyphs stay\n", src.name);
    }
    return atlas;
}

/* Where our glyph sits in the ROM glyph's texel space: texel x = font x *
 * scale_x + x_offset, texel y = baseline - font y * scale_y. */
struct Placement {
    float scale_x = 0, scale_y = 0, x_offset = 0, baseline = 0, atlas_scale = 0;
    Box box{};
    int image_w = 0, image_h = 0;
    const Cell *cell = nullptr;
};

/* The ROM capital's ink as it reads on screen, from its bitmap. Its top and
 * bottom rows are faint anti-aliasing and its ink peaks near 85%, so neither
 * the bitmap height nor the rows' summed ink matches what players see. The
 * edges are taken where the rows' peak intensity, interpolated between row
 * centres as a filtered draw does, crosses a quarter of the glyph's peak;
 * for Bank Gothic's H that is 6.7 of its 8 rows, which matched on-screen
 * captures (the 720p mission hints' ink height, against 2 px taller when
 * scaled to all 8 rows and shorter when scaled to the summed ink). The font's
 * own small-capital proportion then sets the lowercase height. height is in
 * texels; bottom is the
 * texel y of the ink's foot within the bitmap, where text sits. */
bool rom_ink(const RomGlyph &glyph, float &height, float &bottom) {
    if (glyph.pixels == nullptr || glyph.height <= 0 || glyph.width <= 0) return false;
    const int stride = (glyph.width + 7) & ~7;
    std::vector<float> rows(size_t(glyph.height), 0.0f);
    float peak = 0;
    for (int y = 0; y < glyph.height; y++) {
        for (int x = 0; x < glyph.width; x++) rows[y] = std::max(rows[y], float(glyph.pixels[y * stride + x]));
        peak = std::max(peak, rows[y]);
    }
    if (peak <= 0) return false;
    const float level = 0.25f * peak;
    int first = 0, last = glyph.height - 1;
    while (rows[first] < level) first++;
    while (rows[last] < level) last--;
    /* Interpolate each edge between the outermost inked row's centre and its
     * neighbour's (or a blank row past the bitmap). */
    auto edge = [&](int inked, int outside) {
        const float in = rows[inked], out = (outside >= 0 && outside < glyph.height) ? rows[outside] : 0.0f;
        const float t = (in - level) / std::max(in - out, 1.0f);
        return (inked + 0.5f) + (outside - inked) * t;
    };
    const float top = edge(first, first - 1);
    bottom = edge(last, last + 1);
    height = bottom - top;
    return height > 0;
}

/* Horizontal room past the ROM glyph's own width before ours is squeezed,
 * in texels: about half the usual gap on each side. */
constexpr float kWidthSlack = 0.4f;

bool place(const Glyph &glyph, Placement &out) {
    if (glyph.font < 0 || glyph.font >= kFonts) return false;
    const Atlas &atlas = font_atlas(glyph.font);
    if (!atlas.ok) return false;
    const RomGlyph &ref = g_fonts[glyph.font]['H' - 0x21];
    const Cell &cell = atlas.cells[glyph.index];
    float cap = 0, foot = 0;
    if (!cell.present || !rom_ink(ref, cap, foot)) return false;
    out.cell = &cell;
    out.scale_y = cap / atlas.cap_height;                               /* ROM texels per font unit */
    out.atlas_scale = atlas.px_per_em / atlas.units_per_em;            /* atlas pixels per font unit */
    const float ink_units = cell.ink_right - cell.ink_left;
    const float room = glyph.rom.width + kWidthSlack;
    out.scale_x = (ink_units * out.scale_y > room && ink_units > 0) ? room / ink_units : out.scale_y;
    const float ink = ink_units * out.scale_x;
    out.x_offset = (glyph.rom.width - ink) * 0.5f - cell.ink_left * out.scale_x;
    out.baseline = float(ref.baseline) + foot - float(glyph.rom.baseline);
    const float px0 = cell.plane_left * out.scale_x + out.x_offset, px1 = cell.plane_right * out.scale_x + out.x_offset;
    const float py0 = out.baseline - cell.plane_top * out.scale_y, py1 = out.baseline - cell.plane_bottom * out.scale_y;
    const float density_x = out.atlas_scale / out.scale_x, density_y = out.atlas_scale / out.scale_y;  /* image px per texel */
    out.box.x0 = std::floor(std::fmin(0.0f, px0));
    out.box.y0 = std::floor(std::fmin(0.0f, py0));
    out.image_w = int(std::ceil((std::fmax(float(glyph.rom.width), px1) - out.box.x0) * density_x));
    out.image_h = int(std::ceil((std::fmax(float(glyph.rom.height), py1) - out.box.y0) * density_y));
    out.box.x1 = out.box.x0 + out.image_w / density_x;
    out.box.y1 = out.box.y0 + out.image_h / density_y;
    return out.image_w > 0 && out.image_h > 0;
}

}  // namespace

const Glyph *find(const uint8_t *addr) {
    auto it = g_registry.find(addr);
    return it == g_registry.end() ? nullptr : &it->second;
}

bool usable(const Glyph &glyph) {
    Placement p;
    return place(glyph, p);
}

void rom_size(const Glyph &glyph, int &width, int &height) {
    width = glyph.rom.width;
    height = glyph.rom.height;
}

Box box(const Glyph &glyph) {
    Placement p;
    return place(glyph, p) ? p.box : Box{0, 0, float(glyph.rom.width), float(glyph.rom.height)};
}

bool image(const Glyph &glyph, std::vector<uint8_t> &rgba, uint32_t &width, uint32_t &height) {
    Placement p;
    if (!place(glyph, p)) return false;
    const Atlas &atlas = font_atlas(glyph.font);
    const Cell &cell = *p.cell;
    const float density_x = p.atlas_scale / p.scale_x, density_y = p.atlas_scale / p.scale_y;
    width = uint32_t(p.image_w);
    height = uint32_t(p.image_h);
    rgba.assign(size_t(width) * height * 4, 0);
    auto texel = [&](int x, int y, int c) -> float {
        if (x < cell.atlas_x || y < cell.atlas_y || x >= cell.atlas_x + cell.atlas_w || y >= cell.atlas_y + cell.atlas_h) {
            return 0.0f;  /* past the cell: far outside */
        }
        return atlas.rgba[(size_t(y) * atlas.width + x) * 4 + c];
    };
    for (uint32_t j = 0; j < height; j++) {
        for (uint32_t i = 0; i < width; i++) {
            const float tx = p.box.x0 + (i + 0.5f) / density_x, ty = p.box.y0 + (j + 0.5f) / density_y;
            const float fx = (tx - p.x_offset) / p.scale_x, fy = (p.baseline - ty) / p.scale_y;
            const float ax = cell.atlas_x + (fx - cell.plane_left) * p.atlas_scale - 0.5f;
            const float ay = cell.atlas_y + (cell.plane_top - fy) * p.atlas_scale - 0.5f;
            const int x0 = int(std::floor(ax)), y0 = int(std::floor(ay));
            const float u = ax - x0, v = ay - y0;
            uint8_t *dst = &rgba[(size_t(j) * width + i) * 4];
            for (int c = 0; c < 4; c++) {
                const float value = texel(x0, y0, c) * (1 - u) * (1 - v) + texel(x0 + 1, y0, c) * u * (1 - v)
                                    + texel(x0, y0 + 1, c) * (1 - u) * v + texel(x0 + 1, y0 + 1, c) * u * v;
                dst[c] = uint8_t(std::lround(std::fmin(255.0f, std::fmax(0.0f, value))));
            }
        }
    }
    return true;
}

}  // namespace open_fonts

extern "C" void portOpenFontsGlyph(int font, int ch, const unsigned char *pixels, int width, int height, int baseline) {
    using namespace open_fonts;
    if (font < 0 || font >= kFonts || ch < 0x21 || ch > 0x7e || pixels == nullptr) return;
    RomGlyph &slot = g_fonts[font][ch - 0x21];
    if (slot.pixels) g_registry.erase(slot.pixels);  /* the font reloaded at a new address */
    slot = RomGlyph{pixels, width, height, baseline};
    g_registry[pixels] = Glyph{font, ch - 0x21, slot};
}
